def dfs_stack(adj, start):
    seen = set()
    stack = [start]
    order = []
    while stack:
        u = stack.pop()
        if u in seen:
            continue
        seen.add(u)
        order.append(u)
        for v in sorted(adj[u], reverse=True):
            if v not in seen:
                stack.append(v)
    return order

def count_components(adj):
    seen = set()
    count = 0
    for s in adj:
        if s in seen:
            continue
        count += 1
        seen.add(s)
        stack = [s]
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
    return count

def has_cycle(rules):
    state = {r: "new" for r in rules}

    def visit(u):
        state[u] = "active"
        for v in rules[u]:
            if state[v] == "active":
                return True
            if state[v] == "new" and visit(v):
                return True
        state[u] = "done"
        return False

    return any(state[r] == "new" and visit(r) for r in rules)
